#ifndef PLANTS_WIND_GLSL
#define PLANTS_WIND_GLSL

// Waving plants, for core/terrain.vsh. Plants are recognized from what a vertex shader has: they are in the
// cutout layer (ALPHA_CUTOUT 0.5), tinted by the biome (grass, ferns, tall grass, sugar cane, vines), and off
// the block grid (cross models are inset by a pixel, vines stand off the wall; the grass block, also tinted
// and cutout, is on the grid and must not move, or the ground would crack).
//
// Under Sodium, Sodium's terrain shader does the same (assets/sodium/), with its own clock.
//
// A vertex can't tell the top of a plant from its base: vertex indices change from run to run and between
// backends, UV0 lies on sprite corners, shared with the neighbouring sprites in the atlas, and both ends are at
// whole block heights. So the whole plant sways, a little, and the phase of the wind changes with height, so
// that a plant's top and base don't move together: it bends more than it slides.

const float PLANTS_WIND_AMPLITUDE = 0.045;   // blocks

bool plants_is_plant(vec3 worldPosition, vec4 tint) {
    vec2 f = fract(worldPosition.xz);
    bool offGrid = any(greaterThan(min(f, 1.0 - f), vec2(0.01)));
    bool tinted = max(tint.r, max(tint.g, tint.b)) - min(tint.r, min(tint.g, tint.b)) > 0.05;
    return offGrid && tinted;
}

// The wind's offset (x, z) at a world position. time goes from 0 to 1 every 1200 s, and every frequency is a
// whole number of cycles per wrap, so the plants don't jump when it wraps. In core/terrain it is GameTime.
// Sodium's terrain shader has no GameTime, but u_CurrentTime, the milliseconds since its region (8 x 4 x 8
// sections) was created: plants_wind_time_sodium turns it into the same kind of clock. It starts at a different
// moment in each region, which only shifts the phase of the wind there: plants on either side of a region's
// border don't touch, so it doesn't show.
vec2 plants_wind(vec3 p, float gameTime) {
    const float TAU = 6.28318531;
    float gust = 0.6 + 0.4 * sin(TAU * gameTime * 37.0 + p.x * 0.11 + p.z * 0.07);
    float x = sin(TAU * gameTime * 520.0 + p.x * 0.8 + p.z * 0.3 + p.y * 1.7)
            + 0.4 * sin(TAU * gameTime * 1130.0 + p.x * 2.1 - p.y * 2.3);
    float z = sin(TAU * gameTime * 470.0 + p.z * 0.9 - p.x * 0.2 + p.y * 1.9)
            + 0.4 * sin(TAU * gameTime * 1270.0 + p.z * 2.4 + p.y * 2.1);
    return PLANTS_WIND_AMPLITUDE * gust * vec2(x, z) / 1.4;
}

float plants_wind_time_sodium(int currentTimeMs) {
    return float(currentTimeMs % 1200000) / 1200000.0;
}

#endif

