vec3 pos = Position + (ChunkPosition - CameraBlockPos) + CameraOffset;
#ifdef ALPHA_CUTOUT
vec3 world = Position + vec3(ChunkPosition);
if (ALPHA_CUTOUT > 0.4 && plants_is_plant(world, Color)) {
    pos.xz += plants_wind(world, GameTime);
}
#endif

vec3 position = _vert_position + translation;
// Sodium's position is relative to the camera: the wind and the grid test use the position inside the
// region, whose origin is on the block grid.
#ifdef ALPHA_CUTOUT
vec3 inRegion = _vert_position + _get_draw_translation(_draw_id);
if (ALPHA_CUTOUT > 0.4 && plants_is_plant(inRegion, _vert_color)) {
    position.xz += plants_wind(inRegion, plants_wind_time_sodium(u_CurrentTime));
}
#endif
